        && drwGetInfo["LearningLevel"] != null && drwGetInfo["LearningLevel"] != DBNull.Value)
    {
        string strLevel = drwGetInfo["LearningLevel"].ToString().Trim();
        if (strLevel != "")
            return strLevel;
    }

    if (lookupStudentCollectionPeriodID.EditValueString == null || lookupStudentCollectionPeriodID.EditValueString.Trim() == "")
        return "";

    DataRow[] rows = SIM_StudentCollectionPeriodService.Table.Select(
        "StudentCollectionPeriodID = '" + lookupStudentCollectionPeriodID.EditValueString.Replace("'", "''") + "'");
    if (rows.Length > 0 && rows[0]["LearningLevel"] != null && rows[0]["LearningLevel"] != DBNull.Value)
        return rows[0]["LearningLevel"].ToString().Trim();

    return "";
}

